import java.util.Scanner; 

public class ReverseString { 

    // General recursive function to reverse a string 
    public static String reverseString(String s) { 
        // Base case 
        if (s.length() <= 1) { 
            return s; 
        } 
        // Recursive case 
        return reverseString(s.substring(1)) + s.charAt(0); 
    } 
